architecture.h4_f:
msg = CBOR{v:1, text, reply_to, sent_at}
ct = AES-GCM-256-Encrypt(k, nonce, msg, aad=room_id)
POST /api/rooms/{id}/messages {ciphertext: hex(ct), nonce: hex}

cryptoWire.h1_f:
pt = CBOR{v:1, text, reply_to?, thread_id?, mentions?, sent_at}
ct = AES-GCM-256-Encrypt(room_key, nonce, pt, aad=hex(room_id))
ledning = CBOR{
  v: 1,
  chiffertekst: hex(ct), // variabel længde
  nonce: hex(12 B),
  sender_pseudo: hex(16 B),
  sendt_at: unix_ms
}

cryptoWire.h5_f:
ydre = CBOR{
  source_node: hex32,
  target_user: int64,
  indre_cifertekst: bytes,
  indre_nonce: bytes,
  sendt_at: unix_ms
}
sig = Ed25519-Sign(kilde_privat, ydre)
POST /federation/deliver { konvolut: ydre, sig: hex64 }

auth.h1_f:
POST /api/autentificering/register
  { brugernavn, adgangskode, x25519_public_key, display_name, phone?, email?, avatar_emoji }

Svar 201 Oprettet:
  { access_token, refresh_token, user_id, username, ... }

auth.h3_f:
access_token nyttelast:
  { sub: user_id, jti: device_id, typ: "access", exp: now + 15min }
refresh_token nyttelast:
  { sub: user_id, jti: device_id, typ: "refresh", exp: now + 30d }

HS256-signeret med nodens 64-byte hemmelighed fra .env

auth.h4_f:
register_begin(): udfordring = rand(32)
                    optioner = { rp.id, user.id, pubKeyCredParams, challenge }
                    returmuligheder

register_finish(attestation):
  verificer attestation mod TPM / Secure Enclave root CA
  gem { credential_id, public_key, counter: 0 }

auth.h7_f:
POST /api/authentication/qr/begin
  → { nonce: 128-bit hex, ttl: 60 }
QR nyttelast = { nonce, user_id, server: "https://node.example" }

POST /api/authentication/qr/verify { nonce }
  → ny enhed registreret; JWT'er vendte tilbage.

rooms.h6_f:
sender_pseudo = HMAC-SHA256(rum_pseudo_salt, sender_id)[:16] // 32 hex
ciphertext = AES-GCM-Encrypt(room_key, nonce, CBOR_payload, aad=room_id)

Fan-out ramme: { type:"m", room, msg:{id, ct, nonce, sender_pseudo, sent_at} }

files.h2_f:
init POST /api/files/resumable/init {filnavn, størrelse, chunk_size_hint}
            ← {upload_id, chunk_size}
chunk PUT /api/files/resumable/{upload_id}/chunk/{offset} <ct bytes>
            ← 204
færdiggør POST /api/files/resumable/{upload_id}/finalise {plain_blake3}
            ← 201 {file_id, url}
TTL på ufærdig: 24 timer

files.h4_f:
deny_list = {
  "applikation/x-dosexec",
  "applikation/x-sharedlib",
  "applikation/x-mach-binær",
}
if magic.from_buffer(buf[:1024]) i deny_list: returner 415

presence.h1_f:
klient: ved første tastetryk → send {type:"t", state:"start"}
         ikke flere sender i 3 s, medmindre tilstanden ændres
         10 s efter sidste tastetryk → send {type:"t", state:"stop"}
modtager: autostop 10 s efter sidste "start", hvis der ikke kom noget "stop".

calls.h1_f:
POST /api/calls/{room_id}/start {video, audio} → call_id
WS udsendes {type:"c", kind:"invite", call_id}
WS udsendelse {type:"c", kind:"offer", sdp}
WS udsendelse {type:"c", kind:"answer", sdp}
WS udsendelse {type:"c", type:"candidate",ice} × N
POST /api/calls/{call_id}/end

federation.h2_f:
konvolut = {
  source_node: hex32,
  target_user: int64,
  indre_cifertekst: bytes,
  indre_nonce : bytes,
  sendt_at: unix_ms,
}
sig = Ed25519Sign(kilde_privat, CBOR(konvolut))
POST /federation/deliver { konvolut, sig }

gossip.h3_f:
annonce = {pubkey, endpoint, advertised_at}
sig = Ed25519-Sign(pubkey_priv, CBOR(annonce))
sladder nyttelast: [..., {ad, sig}, ...]

modtager: verificere sig mod ad.pubkey → gem iff ok
yderligere: PoW på 2^18 foranstillede nuller på {pubkey, endpoint}

stealth.h2_f:
ClientHello bytes = chrome_120_template med {
  tilfældig = vores tilfældige,
  server_name = vores værtsnavn (eller ECH-indpakket),
  session_id = vores sessions-id,
}
JA4 = t13d_xxxx_xxxx_xxxx (matcher den aktuelle Chrome-stabilitet)

stealth.h4_f:
DoH: POST https://cloudflare-dns.com/dns-query {navn: x.vortexx.sol}
ECH: ClientHello.extensions += encrypted_sni(public_key_from_HTTPS_record)
DGA: domæne(t) = base32( SHA256(frø ∥ YYYY-MM-DD) )[:16] + ".eksempel"

push.h4_f:
iOS NSE: didReceive(request) { decrypt(request.content.userInfo) }
Android FCM: onMessageReceived(remoteMessage) { decrypt(remoteMessage.data) }
Web SW: self.addEventListener('push', e => dekrypter(e.data))

controller.h2_f:
værktøj = tegn_værktøj
input = kildetræ, nøgler/frigivelse.nøgle
manifest = {
  version: "0.1.0",
  bygget_at: unix_ms,
  filer: [{sti, sha256, størrelse}, ...]
}
sig = Ed25519-Sign(release_priv, CBOR(manifest))
output = INTEGRITY.sig.json = {manifest, underskrevet_af: pub_hex, sig: sig_hex}

bots.h1_f:
opret: POST /api/bots {brugernavn, displaynavn, kode}
          → {bot_id, token, pubkey}
Kør: i gang (coroutine inde i node)
      OR ekstern (long-poll /api/bots/{id}/updates, token-auth'd)
besked: {tekst, signatur: Ed25519-Sign(bot_priv, canonical_msg)}

bots.h2_f:
på /start {
  udsende "Velkommen, {ctx.first_name}"
}
på /add <item> {
  state.list = (state.list eller []) + [ctx.args.item]
  udsende "Tilføjet: {ctx.args.item}"
}

security.h4_f:
canary.txt (dagligt):
  {dato, sig: Ed25519-Sign(release_priv, dato)}
klient verificerer → fraværende eller ugyldig ⇒ mistanke om kompromittering

nødsituation:
  admin POST /api/admin/revoke-all {reason}
  node-udsendelser {type:"n", begivenhed:"compromise", reason}
  klienter tørrer nøgler, tvinger genstart

debugging.h2_f:
rate histogrammer (pr. rute + metode):
  vortex_http_anmodninger_total{rute,metode,status}
  vortex_http_request_duration_seconds_bucket{rute,metode,le}

websocket målere:
  vortex_ws_connections{node}
  vortex_ws_fanout_queue_depth{rum,bruger}

tilpassede tællere:
  vortex_messages_sent_total{room_type}
  vortex_calls_started_total{kind}

login.h4_f:
ved succes: 201 + JWT kuvert (samme form som register)
på 2FA nødvendig: 200 { "needs_2fa": true } (ingen JWT endnu)
ved fejl: 401 { "error":"invalid_credentials" }

apns.h1_f:
POST https://api.push.apple.com/3/device/<device_token>
Overskrifter: apns-topic: <bundle_id>, apns-push-type: alert, apns-collapse-id: room:42
Body: {aps: {alert: {title, body}}, data: <sealed>}

bmp.h1_f:
mailbox_id = HKDF(recipient_pubkey, info="bmp-v1", len=32)
Indbetaling: POST /bmp/indbetaling {mailbox_id, blob ≤1MB}
Afhentning: GET /bmp/beskeder (godkendt)

controller.h1_f:
GET /v1/integrity → {status, signed_by, matched, mismatched, …}
GET /v1/sundhed → {status, version, pubkey, stats}
GET /v1/indgange → [{protokol, url}, …]
GET /v1/spejle → [controller_url, …]

fcm.h1_f:
POST https://fcm.googleapis.com/v1/projects/<project>/messages:send
Autorisation: Bærer <oauth2_token>
Brødtekst: {meddelelse: {token: <device>, data: {...sealed...}, android: {collapse_key}}}

federation.h1_f:
kuvert = {source_node, target_user, inner_ct, inner_nonce, sent_at}
sig = Ed25519-Sign(kilde_privat, CBOR(kuvert))
POST /federation/deliver {konvolut, sig}
B verificerer: sig mod federations[source_node].pubkey

fts5.h1_f:
CREATE VIRTUAL TABLE messages_fts USING fts5(
  indhold, -- tokeniseret kolonne
  room_id UNINDEXED,
  tokenize = 'unicode61 remove_diacritics 2'
);
forespørgsel: SELECT rowid FROM messages_fts WHERE indhold MATCH 'foo'

gravitix.h1_f:
på /start { emit "Velkommen, {ctx.first_name}" }
på /add <item> {
  state.list = (state.list eller []) + [ctx.args.item]
  udsende "Tilføjet: {ctx.args.item}"
}

prekey.h1_f:
bundle = {
  identitet_pk,
  signed_prekey_pk,
  signed_prekey_sig = Ed25519-Sign(identity_priv, signed_prekey_pk),
  one_time_prekeys: [pk_0, pk_1, ..., pk_9]
}

vapid.h1_f:
VAPID nøgler: Ed25519 nøglepar pr. node
underskriv JWT: {aud: push_service_origin, exp: now + 12h, sub: mailto:ops@example}
push request headers: Autorisation: vapid t=<jwt>, k=<vapid_public_key>
